use verus::prelude::*;

// Compute ⌈n / (2*d + 1)⌉ safely.
//
// Each inspector covers up to (2*d + 1) items, so the minimum
// number of inspectors is the ceiling of n / coverage.
//
#[requires(n >= 0)]
#[requires(d >= 0)]           // ⇒ coverage = 2*d+1 ≥ 1, so division is well‐defined
#[ensures(|result: i8| {
    let coverage = 2*d + 1;
    // result is nonnegative
    result >= 0
    // (result - 1)*coverage < n : if you used one fewer inspectors you
    // wouldn't cover all n items
    && (result - 1) * coverage < n
    // result*coverage ≥ n : with result inspectors you do cover all n
    && n <= result * coverage
})]
fn min_inspectors(n: i8, d: i8) -> i8 {
    // Each inspector covers up to `2*d + 1` items.
    let coverage = 2 * d + 1;
    // The minimum number of inspectors is the ceiling of n / coverage.
    // We compute ceil(a/b) as (a + b - 1) / b in integer arithmetic.
    (n + coverage - 1) / coverage
}

